	/** 
	 * jumpstart the process by instantiating2 Visualization
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		visualizationId = VisualizationService.getVisualizationInstance()
		.createVisualization( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		VisualizationService.getVisualizationInstance()
				.createVisualization( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.visualizationSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Visualization : " + successValue.getVisualizationId());
							  if (successValue.getVisualizationId().equals(visualizationId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfVisualizationList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Visualization test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on visualization consumed")
					);
			subscriber.visualizationSubscribe( visualizationId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Visualization : " + successValue.getVisualizationId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfVisualizationList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on visualization for visualizationId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Visualization. 
	 */
	protected Visualization read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Visualization" );

		Visualization entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Visualization with primary key" );
		msg.append( visualizationId );
		
		VisualizationFetchOneSummary fetchOneSummary = new VisualizationFetchOneSummary( visualizationId );

		try {
			entity = VisualizationService.getVisualizationInstance().getVisualization( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Visualization " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Visualization.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Visualization." );

		StringBuilder msg = new StringBuilder( "Failed to update a Visualization : " );        
		Visualization entity = read();
		UpdateVisualizationCommand command = generateUpdateCommand();
		command.setVisualizationId(entity.getVisualizationId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Visualization." );

			// for use later on...
			visualizationId = entity.getVisualizationId();

			VisualizationService proxy = VisualizationService.getVisualizationInstance();  

			proxy.updateVisualization( command ).get();

			LOGGER.info( "-- Successfully saved Visualization - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + visualizationId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Visualization.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Visualization." );

		Visualization entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Visualization with id " + visualizationId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Visualization with id " + visualizationId );

			throw e;
		}

		try{
			VisualizationService.getVisualizationInstance().delete( new DeleteVisualizationCommand( entity.getVisualizationId() ) ).get();
			LOGGER.info( "-- Successfully deleted Visualization with id " + visualizationId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Visualization with id " + visualizationId );

			throw e;
		}
	}

	/**
	 * get all Visualizations.
	 */
	protected List<Visualization> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Visualizations:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Visualization : " );        
		List<Visualization> collection  = new ArrayList<>();

		try {
			// call the static get method on the VisualizationService
			collection = VisualizationService.getVisualizationInstance().getAllVisualization();
			assertNotNull( collection, "An Empty collection of Visualization was incorrectly returned.");
			
			// Now print out the values
			Visualization entity = null;            
			Iterator<Visualization> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getVisualizationId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

